class Shape {                       // parent / superclass
    void draw() {
        System.out.println("Drawing a shape");
    }
}

class Circle extends Shape {         // child / subclass
    @Override
    void draw() {                    // parent এর draw() কে override করল
        System.out.println("Drawing a circle");
    }
}

class Rectangle extends Shape {
    @Override
    void draw() {
        System.out.println("Drawing a rectangle");
    }
}

public class OverrideDemo {
    public static void main(String[] args) {

        Shape s;                     // parent type এর একটিমাত্র reference

        s = new Shape();
        s.draw();                    // Drawing a shape

        s = new Circle();            // upcasting
        s.draw();                    // Drawing a circle    ← runtime এ ঠিক হয়

        s = new Rectangle();
        s.draw();                    // Drawing a rectangle ← runtime এ ঠিক হয়
    }
}

/*  Output:
    Drawing a shape
    Drawing a circle
    Drawing a rectangle                                     */
